<?php require __DIR__.'/app/core.php'; $slug=$_GET['slug']??''; $post=null; foreach(posts_all() as $p){ if(($p['slug']??'')===$slug){$post=$p; break;}} if(!$post){http_response_code(404); header_html('blog',['title'=>'Yazı bulunamadı','desc'=>'Yazı bulunamadı']); echo '<section class="page"><h1>Yazı bulunamadı</h1></section>'; footer_html(); exit;} header_html('blog',['title'=>$post['title'].' | Xtanbul Yazılım Agent','desc'=>$post['summary']]); ?><article class="page article"><h1><?=e($post['title'])?></h1><p class="lead"><?=e($post['summary'])?></p><small><?=e($post['created_at']??'')?></small><div class="content"><?=nl2br(e($post['content']))?></div></article><?php footer_html(); ?>